<?php require_once '../config.php';require_admin();$rows=db()->query('SELECT id,name,email,phone,points,created_at FROM customers ORDER BY id DESC')->fetchAll();page_start('Customer management');?><section class="panel"><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>Points</th><th>Joined</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['phone'])?></td><td><?=number_format($r['points'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div></section><?php page_end();?>
